type ProductForm = { id?: number; name: string; nameAr: string; nameEn: string; slug: string; category: string; price: string; oldPrice: string; discountPercent: string; discountActive: boolean; discountStartsAt: string; discountEndsAt: string; stock: string; description: string; imageUrl: string; images: string; specifications: string; variants: string; featured: boolean; active: boolean };
