function toProductForm(product: ApiProduct): ProductForm {
  return { id: product.backendId, name: product.name, nameAr: product.nameAr || product.name, nameEn: product.nameEn || product.name, slug: product.id, category: product.category, price: String(product.basePrice ?? product.price), oldPrice: product.oldPrice ? String(product.oldPrice) : '', discountPercent: product.discountPercent ? String(product.discountPercent) : '', discountActive: Boolean(product.discountActive), discountStartsAt: product.discountStartsAt ? String(product.discountStartsAt).slice(0, 16) : '', discountEndsAt: product.discountEndsAt ? String(product.discountEndsAt).slice(0, 16) : '', stock: String(product.stock), description: product.description, imageUrl: product.image, images: JSON.stringify(product.images || []), specifications: product.specifications.join(', '), variants: JSON.stringify(product.variants || []), featured: Boolean(product.isBestSeller), active: product.active !== false };
}

