  const remove = async (product: ApiProduct) => { if (!product.backendId) return; const result = await confirmAction('طھط¹ط·ظٹظ„ ط§ظ„ظ…ظ†طھط¬طں', `ط³ظٹط®طھظپظٹ آ«${product.name}آ» ظ…ظ† ط§ظ„ظ…طھط¬ط±طŒ ظˆظٹظ…ظƒظ†ظƒ ط¥ط¹ط§ط¯طھظ‡ ظ„ط§ط­ظ‚ظ‹ط§.`); if (!result.isConfirmed) return; showLoading('ط¬ط§ط±ظچ طھط¹ط·ظٹظ„ ط§ظ„ظ…ظ†طھط¬â€¦'); try { await deleteProduct(product.backendId); closeAlert(); await onRefresh(); await notifySuccess('طھظ… طھط¹ط·ظٹظ„ ط§ظ„ظ…ظ†طھط¬'); } catch (error) { closeAlert(); await notifyError('طھط¹ط°ط± طھط¹ط·ظٹظ„ ط§ظ„ظ…ظ†طھط¬', error instanceof Error ? error.message : 'ط­ط¯ط« ط®ط·ط£ ط؛ظٹط± ظ…طھظˆظ‚ط¹.'); } };
