function ImageUploadField({ form, setForm }: { form: ProductForm; setForm: (form: ProductForm) => void }) {
  const images = parseImageList(form.images);
  const updateImages = (next: string[]) => setForm({ ...form, imageUrl: next[0] || '', images: JSON.stringify(next) });
  const readImage = (file: File) => new Promise<string>((resolve, reject) => {
    if (!file.type.startsWith('image/')) { reject(new Error('ظٹظ…ظƒظ† ط±ظپط¹ ظ…ظ„ظپط§طھ ط§ظ„طµظˆط± ظپظ‚ط·.')); return; }
    if (file.size > 5 * 1024 * 1024) { reject(new Error('ط­ط¬ظ… ط§ظ„طµظˆط±ط© ظٹط¬ط¨ ط£ظ„ط§ ظٹطھط¬ط§ظˆط² 5 ظ…ظٹط¬ط§ط¨ط§ظٹطھ.')); return; }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('طھط¹ط°ط± ظ‚ط±ط§ط،ط© ط§ظ„طµظˆط±ط©.'));
    reader.onload = () => {
      const image = new Image();
      image.onerror = () => reject(new Error('ط§ظ„طµظˆط±ط© ط؛ظٹط± طµط§ظ„ط­ط©.'));
      image.onload = () => {
        const maxSize = 1400;
        const scale = Math.min(1, maxSize / Math.max(image.width, image.height));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(image.width * scale));
        canvas.height = Math.max(1, Math.round(image.height * scale));
        canvas.getContext('2d')?.drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL(file.type === 'image/png' ? 'image/png' : 'image/jpeg', 0.82));
      };
      image.src = String(reader.result);
    };
    reader.readAsDataURL(file);
  });
  const onFiles = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;
    try { updateImages([...images, ...(await Promise.all(files.map(readImage)))]); }
    catch (error) { await notifyError('طھط¹ط°ط± ط±ظپط¹ ط§ظ„طµظˆط±ط©', error instanceof Error ? error.message : 'ط­ط¯ط« ط®ط·ط£ ط؛ظٹط± ظ…طھظˆظ‚ط¹.'); }
    event.target.value = '';
  };
  return <div className="sm:col-span-2 rounded-xl border border-dashed border-primary/40 bg-background p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">طµظˆط± ط§ظ„ظ…ظ†طھط¬</p><p className="mt-1 text-xs text-muted-foreground">ط§ط±ظپط¹ طµظˆط±ط© ط£ظˆ ط£ظƒط«ط± ظ…ظ† ط¬ظ‡ط§ط²ظƒ. ط£ظˆظ„ طµظˆط±ط© ط³طھظƒظˆظ† ط§ظ„طµظˆط±ط© ط§ظ„ط£ط³ط§ط³ظٹط©.</p></div><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground"><Plus className="h-4 w-4" /> ط±ظپط¹ طµظˆط±ط©<input type="file" accept="image/*" multiple onChange={onFiles} className="hidden" /></label></div>{images.length > 0 && <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{images.map((image, index) => <div key={`${image.slice(0, 30)}-${index}`} className="relative overflow-hidden rounded-xl border border-border bg-card"><img src={image} alt={`طµظˆط±ط© ط§ظ„ظ…ظ†طھط¬ ${index + 1}`} className="aspect-square w-full object-cover" /><button type="button" onClick={() => updateImages(images.filter((_, imageIndex) => imageIndex !== index))} className="absolute right-2 top-2 rounded-full bg-white/90 p-1.5 text-destructive shadow" aria-label="ط­ط°ظپ ط§ظ„طµظˆط±ط©"><X className="h-4 w-4" /></button>{index === 0 && <span className="absolute bottom-2 right-2 rounded-md bg-black/70 px-2 py-1 text-[10px] font-bold text-white">ط§ظ„طµظˆط±ط© ط§ظ„ط£ط³ط§ط³ظٹط©</span>}</div>)}</div>}</div>;
}

