function OfferRow({ product, onRefresh }: { product: ApiProduct; onRefresh: () => Promise<void> }) {
  const [percent, setPercent] = useState(String(product.discountPercent || 0));
  const [active, setActive] = useState(Boolean(product.discountActive));
  const [endsAt, setEndsAt] = useState(product.discountEndsAt ? String(product.discountEndsAt).slice(0, 16) : '');
  const [saving, setSaving] = useState(false);
  const save = async () => { if (!product.backendId) return; setSaving(true); showLoading('ط¬ط§ط±ظچ ط­ظپط¸ ط§ظ„ط¹ط±ط¶â€¦'); try { await updateProduct(product.backendId, { discountPercent: Number(percent) || 0, discountActive: active, discountStartsAt: null, discountEndsAt: endsAt || null }); closeAlert(); await onRefresh(); await notifySuccess('طھظ… ط­ظپط¸ ط§ظ„ط¹ط±ط¶', active && Number(percent) > 0 ? `ط®طµظ… ${percent}% ظ…ظپط¹ظ„ ط¹ظ„ظ‰ ط§ظ„ظ…ظ†طھط¬.` : 'طھظ… ط¥ظٹظ‚ط§ظپ ط§ظ„ط®طµظ… ط¹ظ„ظ‰ ط§ظ„ظ…ظ†طھط¬.'); } catch (error) { closeAlert(); await notifyError('طھط¹ط°ط± ط­ظپط¸ ط§ظ„ط¹ط±ط¶', error instanceof Error ? error.message : 'ط­ط¯ط« ط®ط·ط£ ط؛ظٹط± ظ…طھظˆظ‚ط¹.'); } finally { setSaving(false); } };
  return <div className="flex flex-col gap-3 rounded-xl bg-secondary p-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex items-center gap-3"><img src={product.image} alt="" className="h-12 w-12 rounded-xl object-cover" /><div><p className="font-semibold">{product.name}</p><p className="text-xs text-muted-foreground">{active && Number(percent) > 0 ? `${percent}% ط®طµظ… ظ…ظپط¹ظ„ آ· ${money(product.price)}` : 'ظ„ط§ ظٹظˆط¬ط¯ ط®طµظ… ظ…ظپط¹ظ„'}</p></div></div><div className="flex flex-wrap items-center gap-2"><label className="flex items-center gap-2 text-xs font-bold">ظ†ط³ط¨ط© ط§ظ„ط®طµظ…<input type="number" min="0" max="100" value={percent} onChange={(event) => setPercent(event.target.value)} className="w-20 rounded-lg border border-border bg-background px-2 py-2 text-sm font-normal" /></label><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" checked={active} onChange={(event) => setActive(event.target.checked)} className="h-4 w-4 accent-primary" />ظ…ظپط¹ظ„</label><label className="flex items-center gap-2 text-xs font-bold">ظٹظ†طھظ‡ظٹ<input type="datetime-local" value={endsAt} onChange={(event) => setEndsAt(event.target.value)} className="rounded-lg border border-border bg-background px-2 py-2 text-xs font-normal" /></label><button onClick={save} disabled={saving} className="rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground">{saving ? 'ط¬ط§ط±ظچ ط§ظ„ط­ظپط¸â€¦' : 'ط­ظپط¸ ط§ظ„ط¹ط±ط¶'}</button></div></div>;
}

